function smart_sort_array($set, $order) {
    usort($set, function ($a, $b) use ($order) {
        // Compare age values based on the given order ('asc' or 'desc')
        if (isset($order)) {
            return $order === 'asc' ? ($a['age'] < $b['age']) : ($a['age'] > $b['age']);
        } else {
